# MythTV Server API Python Library

A comprehensive Python library to interact with the MythTV Services API.

## Installation

```bash
pip install requests
```

## Library Code

```python
"""
MythTV Server API Python Library

A comprehensive library to interact with the MythTV Services API.
"""

import requests
from datetime import datetime
from typing import Optional, List, Dict, Any, Union
from urllib.parse import urljoin, urlencode
import json


class MythTVAPIError(Exception):
    """Custom exception for MythTV API errors."""

    def __init__(self, message: str, status_code: int = None, response: dict = None):
        self.message = message
        self.status_code = status_code
        self.response = response
        super().__init__(self.message)


class MythTVConnection:
    """Base connection class for MythTV API."""

    def __init__(
        self,
        host: str = "localhost",
        port: int = 6544,
        protocol: str = "http",
        username: str = None,
        password: str = None,
        timeout: int = 30
    ):
        """
        Initialize MythTV connection.

        Args:
            host: MythTV backend hostname or IP
            port: MythTV API port (default: 6544)
            protocol: http or https
            username: Optional username for authentication
            password: Optional password for authentication
            timeout: Request timeout in seconds
        """
        self.host = host
        self.port = port
        self.protocol = protocol
        self.base_url = f"{protocol}://{host}:{port}"
        self.timeout = timeout
        self.session = requests.Session()

        if username and password:
            self.session.auth = (username, password)

        self.session.headers.update({
            "Accept": "application/json",
            "Content-Type": "application/json"
        })

    def _make_request(
        self,
        method: str,
        endpoint: str,
        params: dict = None,
        data: dict = None,
        **kwargs
    ) -> dict:
        """Make HTTP request to MythTV API."""
        url = urljoin(self.base_url, endpoint)

        try:
            response = self.session.request(
                method=method,
                url=url,
                params=params,
                json=data,
                timeout=self.timeout,
                **kwargs
            )
            response.raise_for_status()

            if response.content:
                return response.json()
            return {}

        except requests.exceptions.HTTPError as e:
            raise MythTVAPIError(
                f"HTTP Error: {e}",
                status_code=response.status_code,
                response=response.text
            )
        except requests.exceptions.ConnectionError as e:
            raise MythTVAPIError(f"Connection Error: {e}")
        except requests.exceptions.Timeout as e:
            raise MythTVAPIError(f"Timeout Error: {e}")
        except json.JSONDecodeError as e:
            raise MythTVAPIError(f"JSON Decode Error: {e}")

    def get(self, endpoint: str, params: dict = None) -> dict:
        """Make GET request."""
        return self._make_request("GET", endpoint, params=params)

    def post(self, endpoint: str, data: dict = None, params: dict = None) -> dict:
        """Make POST request."""
        return self._make_request("POST", endpoint, params=params, data=data)

    def delete(self, endpoint: str, params: dict = None) -> dict:
        """Make DELETE request."""
        return self._make_request("DELETE", endpoint, params=params)


class MythService:
    """Service for Myth-specific operations."""

    def __init__(self, connection: MythTVConnection):
        self.conn = connection
        self.base_endpoint = "/Myth"

    def get_host_name(self) -> str:
        """Get the backend hostname."""
        response = self.conn.get(f"{self.base_endpoint}/GetHostName")
        return response.get("String", "")

    def get_hosts(self) -> List[str]:
        """Get list of all hosts."""
        response = self.conn.get(f"{self.base_endpoint}/GetHosts")
        return response.get("StringList", [])

    def get_keys(self) -> List[str]:
        """Get list of all setting keys."""
        response = self.conn.get(f"{self.base_endpoint}/GetKeys")
        return response.get("StringList", [])

    def get_setting(self, key: str, hostname: str = None, default: str = None) -> str:
        """Get a setting value."""
        params = {"Key": key}
        if hostname:
            params["HostName"] = hostname
        if default:
            params["Default"] = default

        response = self.conn.get(f"{self.base_endpoint}/GetSetting", params)
        return response.get("String", "")

    def put_setting(self, key: str, value: str, hostname: str = None) -> bool:
        """Set a setting value."""
        params = {"Key": key, "Value": value}
        if hostname:
            params["HostName"] = hostname

        response = self.conn.post(f"{self.base_endpoint}/PutSetting", params=params)
        return response.get("bool", False)

    def get_connection_info(self, pin: str = None) -> dict:
        """Get database connection info."""
        params = {}
        if pin:
            params["Pin"] = pin

        return self.conn.get(f"{self.base_endpoint}/GetConnectionInfo", params)

    def get_storage_group_dirs(
        self,
        group_name: str = None,
        hostname: str = None
    ) -> List[dict]:
        """Get storage group directories."""
        params = {}
        if group_name:
            params["GroupName"] = group_name
        if hostname:
            params["HostName"] = hostname

        response = self.conn.get(f"{self.base_endpoint}/GetStorageGroupDirs", params)
        return response.get("StorageGroupDirList", {}).get("StorageGroupDirs", [])

    def get_time_zone(self) -> dict:
        """Get time zone information."""
        return self.conn.get(f"{self.base_endpoint}/GetTimeZone")

    def get_backend_info(self) -> dict:
        """Get backend information."""
        return self.conn.get(f"{self.base_endpoint}/GetBackendInfo")

    def get_frontend_list(self) -> List[dict]:
        """Get list of connected frontends."""
        response = self.conn.get(f"{self.base_endpoint}/GetFrontends")
        return response.get("FrontendList", {}).get("Frontends", [])

    def send_message(
        self,
        message: str,
        address: str = None,
        udp_port: int = None,
        timeout: int = None
    ) -> bool:
        """Send a message to frontends."""
        params = {"Message": message}
        if address:
            params["Address"] = address
        if udp_port:
            params["udpPort"] = udp_port
        if timeout:
            params["Timeout"] = timeout

        response = self.conn.post(f"{self.base_endpoint}/SendMessage", params=params)
        return response.get("bool", False)


class DvrService:
    """Service for DVR operations."""

    def __init__(self, connection: MythTVConnection):
        self.conn = connection
        self.base_endpoint = "/Dvr"

    def get_recorded_list(
        self,
        start_index: int = 0,
        count: int = None,
        descending: bool = True,
        title_reg_ex: str = None,
        rec_group: str = None,
        storage_group: str = None,
        category: str = None,
        sort: str = None
