        if recorded_id:
            params["RecordedId"] = recorded_id
        if chan_id:
            params["ChanId"] = chan_id
        if start_time:
            params["StartTime"] = start_time.isoformat()

        response = self.conn.get(f"{self.base_endpoint}/GetRecorded", params)
        return response.get("Program", {})

    def get_upcoming_list(
        self,
        start_index: int = 0,
        count: int = None,
        show_all: bool = False,
        record_id: int = None,
        rec_status: int = None
    ) -> dict:
        """Get list of upcoming recordings."""
        params = {"StartIndex": start_index, "ShowAll": show_all}

        if count:
            params["Count"] = count
        if record_id:
            params["RecordId"] = record_id
        if rec_status:
