        params = {"StartIndex": start_index}

        if count:
            params["Count"] = count
        if record_id:
            params["RecordId"] = record_id

        response = self.conn.get(f"{self.base_endpoint}/GetConflictList", params)
        return response.get("ProgramList", {})

