    ) -> dict:
        """Get list of expiring recordings."""
        params = {"StartIndex": start_index}
        if count:
            params["Count"] = count

        response = self.conn.get(f"{self.base_endpoint}/GetExpiringList", params)
        return response.get("ProgramList", {})

