        """Get list of recording groups."""
        response = self.conn.get(f"{self.base_endpoint}/GetRecGroupList")
        return response.get("StringList", [])

    def get_rec_storage_group_list(self) -> List[str]:
        """Get list of recording storage groups."""
        response = self.conn.get(f"{self.base_endpoint}/GetRecStorageGroupList")
        return response.get("StringList", [])

