        preferred_input: int = 0,
        start_offset: int = 0,
        end_offset: int = 0,
        dup_method: str = "Subtitle and Description",
        dup_in: str = "All Recordings",
        rec_group: str = "Default",
        storage_group: str = "Default",
        play_group: str = "Default",
