        max_episodes: int = 0,
        max_newest: bool = False,
        auto_commflag: bool = True,
        auto_transcode: bool = False,
        auto_meta_lookup: bool = True,
        auto_user_job1: bool = False,
        auto_user_job2: bool = False,
        auto_user_job3: bool = False,
        auto_user_job4: bool = False,
        transcoder: int = 0
    ) -> int:
        """Add a new recording schedule."""
        params = {
            "Title": title,
            "ChanId": chan_id,
            "StartTime": start_time.isoformat(),
            "EndTime": end_time.isoformat(),
            "Type": type_,
            "SearchType": search_type,
            "RecPriority": rec_priority,
            "PreferredInput": preferred_input,
            "StartOffset": start_offset,
            "EndOffset": end_offset,
            "DupMethod": dup_method,
            "DupIn": dup_in,
            "RecGroup": rec_group,
            "StorageGroup": storage_group,
            "PlayGroup": play_group,
            "AutoExpire": auto_expire,
            "MaxEpisodes": max_episodes,
            "MaxNewest": max_newest,
            "AutoCommflag": auto_commflag,
            "AutoTranscode": auto_transcode,
            "AutoMetaLookup": auto_meta_lookup,
            "AutoUserJob1": auto_user_job1,
            "AutoUserJob2": auto_user_job2,
            "AutoUserJob3": auto_user_job3,
            "AutoUserJob4": auto_user_job4,
            "Transcoder": transcoder
        }

        response = self.conn.post(f"{self.base_endpoint}/AddRecordSchedule", params=params)
        return response.get("uint", 0)

    def update_record_schedule(self, record_id: int, **kwargs) -> bool:
        """Update a recording schedule."""
        params = {"RecordId": record_id, **kwargs}
        response = self.conn.post(f"{self.base_endpoint}/UpdateRecordSchedule", params=params)
        return response.get("bool", False)

    def remove_record_schedule(self, record_id: int) -> bool:
        """Remove a recording schedule."""
        params = {"RecordId": record_id}
        response = self.conn.post(f"{self.base_endpoint}/RemoveRecordSchedule", params=params)
        return response.get("bool", False)

    def disable_record_schedule(self, record_id: int) -> bool:
        """Disable a recording schedule."""
        params = {"RecordId": record_id}
        response = self.conn.post(f"{self.base_endpoint}/DisableRecordSchedule", params=params)
        return response.get("bool", False)

    def enable_record_schedule(self, record_id: int) -> bool:
        """Enable a recording schedule."""
        params = {"RecordId": record_id}
        response = self.conn.post(f"{self.base_endpoint}/EnableRecordSchedule", params=params)
        return response.get("bool", False)

    def delete_recording(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
        force_delete: bool = False,
        allow_rerecord: bool = False
    ) -> bool:
        """Delete a recording."""
        params = {"ForceDelete": force_delete, "AllowRerecord": allow_rerecord}

        if recorded_id:
            params["RecordedId"] = recorded_id
        if chan_id:
            params["ChanId"] = chan_id
        if start_time:
            params["StartTime"] = start_time.isoformat()

        response = self.conn.post(f"{self.base_endpoint}/DeleteRecording", params=params)
        return response.get("bool", False)

    def undelete_recording(
        self,
        recorded_id: int = None,
